import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`jsonpath`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p><strong>JSONPath</strong> is a query language for JSON, the way XPath is for XML. An expression walks the document from the root and returns every value that matches.</p><blockquote><p>ℹ️ Expressions normally start with <code>$</code>, the root element. Some clients let you drop the leading <code>$.</code>. Implementations differ in the details — <a href="https://www.rfc-editor.org/rfc/rfc9535.html">RFC 9535</a> standardised the syntax in 2024, but older libraries predate it.</p></blockquote><h2>🧭 Syntax</h2><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$</code></td><td>The root element</td></tr><tr><td><code>@</code></td><td>The element currently being filtered</td></tr><tr><td><code>$.store.book[0].title</code></td><td>Dot notation</td></tr><tr><td><code>store.book[0].title</code></td><td>With the <code>$.</code> implied</td></tr><tr><td><code>$[&#39;store&#39;][&#39;book&#39;][0][&#39;title&#39;]</code></td><td>Bracket notation — needed for keys with spaces or dashes</td></tr><tr><td><code>..</code></td><td>Recursive descent, at any depth</td></tr><tr><td><code>*</code></td><td>Wildcard: every element or member</td></tr><tr><td><code>[]</code></td><td>Subscript: index, slice, union or filter</td></tr></tbody></table><h2>🌳 Tree Traversal</h2><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$.parentNode.childNode.field</code></td><td>XPath <code>/parentNode/childNode/@field</code> — the field of every matching child</td></tr><tr><td><code>$..anyChildNode</code></td><td>XPath <code>//anyChildNode</code> — every node with that name, at any depth</td></tr><tr><td><code>$.parentNode.*</code></td><td>XPath <code>/parentNode/*</code> — every child of the node</td></tr><tr><td><code>$..*</code></td><td>Every value in the document</td></tr><tr><td><code>$..book[*].author</code></td><td>The author of every book, however deeply nested</td></tr></tbody></table><h2>🔢 Array Access</h2><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$.myList[0]</code></td><td>First element</td></tr><tr><td><code>$.myList[-1]</code></td><td>Last element</td></tr><tr><td><code>$.myList[*]</code></td><td>Every element</td></tr><tr><td><code>$.myList[2:4]</code></td><td>Slice — index 2 up to, not including, 4</td></tr><tr><td><code>$.myList[:3]</code></td><td>The first three</td></tr><tr><td><code>$.myList[-2:]</code></td><td>The last two</td></tr><tr><td><code>$.myList[::2]</code></td><td>Every second element</td></tr><tr><td><code>$.myList[0,4,5]</code></td><td>A union of specific indexes</td></tr></tbody></table><h2>🔎 Filtering</h2><p>Filters are written <code>[?(...)]</code> — <code>[?...]</code> in RFC 9535 — and keep the elements for which the expression is true.</p><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$.customer[?(@.car)]</code></td><td>Customers that have a <code>car</code> field at all</td></tr><tr><td><code>$.customer[?(@.car == &#39;Ford Fiesta&#39;)]</code></td><td>Customers with a Ford Fiesta</td></tr><tr><td><code>$.customer[?(@.age &gt; 18)]</code></td><td>Adults only</td></tr><tr><td><code>$.customer[?(@.age != 18)]</code></td><td>Everyone but the 18-year-olds</td></tr><tr><td><code>$.book[?(@.price &lt;= 10)]</code></td><td>Also <code>&lt;</code>, <code>&gt;=</code>, <code>==</code></td></tr><tr><td><code>$.book[?(@.title =~ /^The/)]</code></td><td>Regular expression match (implementation-specific)</td></tr></tbody></table><h3>Combining conditions</h3><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$.customer[?(@.age &gt; 18 || @.car == &#39;Ford Fiesta&#39;)]</code></td><td>Logical or</td></tr><tr><td><code>$.customer[?(@.age &lt; 18 &amp;&amp; @.hobby == &#39;Biking&#39;)]</code></td><td>Logical and</td></tr><tr><td><code>$.customer[?(!@.car)]</code></td><td>Logical not</td></tr></tbody></table><h2>🧮 Functions</h2><p>Available in RFC 9535 and in most modern implementations:</p><table><thead><tr><th>Function</th><th>Example</th><th>Returns</th></tr></thead><tbody><tr><td><code>length()</code></td><td><code>$.book[?(length(@.tags) &gt; 2)]</code></td><td>Length of a string, array or object</td></tr><tr><td><code>count()</code></td><td><code>$.book[?(count(@.authors.*) &gt; 1)]</code></td><td>Number of nodes a query matched</td></tr><tr><td><code>match()</code></td><td><code>$.book[?(match(@.isbn, &quot;\\\\d{13}&quot;))]</code></td><td>True when the <strong>whole</strong> string matches</td></tr><tr><td><code>search()</code></td><td><code>$.book[?(search(@.title, &quot;Moon&quot;))]</code></td><td>True when the pattern occurs anywhere</td></tr><tr><td><code>value()</code></td><td><code>$.book[?(value(@.price) &gt; 10)]</code></td><td>The value of a single-node query</td></tr></tbody></table><p>Older Jayway-style implementations instead offer <code>.length()</code>, <code>.min()</code>, <code>.max()</code>, <code>.avg()</code> and <code>.sum()</code> at the end of a path — <code>$.book[*].price.sum()</code>.</p><h2>📄 Worked Example</h2><pre><code class="language-json">{
  &quot;store&quot;: {
    &quot;book&quot;: [
      { &quot;title&quot;: &quot;Sayings of the Century&quot;, &quot;author&quot;: &quot;Nigel Rees&quot;, &quot;price&quot;: 8.95 },
      { &quot;title&quot;: &quot;Moby Dick&quot;, &quot;author&quot;: &quot;Herman Melville&quot;, &quot;price&quot;: 8.99 },
      { &quot;title&quot;: &quot;The Lord of the Rings&quot;, &quot;author&quot;: &quot;J. R. R. Tolkien&quot;, &quot;price&quot;: 22.99 }
    ],
    &quot;bicycle&quot;: { &quot;color&quot;: &quot;red&quot;, &quot;price&quot;: 19.95 }
  }
}
</code></pre><table><thead><tr><th>Expression</th><th>Result</th></tr></thead><tbody><tr><td><code>$.store.book[*].author</code></td><td>All three authors</td></tr><tr><td><code>$..price</code></td><td><code>8.95</code>, <code>8.99</code>, <code>22.99</code>, <code>19.95</code></td></tr><tr><td><code>$.store.book[?(@.price &lt; 10)]</code></td><td>The two cheap books</td></tr><tr><td><code>$.store.book[-1].title</code></td><td><code>&quot;The Lord of the Rings&quot;</code></td></tr><tr><td><code>$..book[?(@.author =~ /Tolkien/)]</code></td><td>The Tolkien entry</td></tr><tr><td><code>$.store.*</code></td><td>The book array and the bicycle object</td></tr></tbody></table><h2>🗺 Output Mapping</h2><table><thead><tr><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>$.[].{Name:name, Age:age, Hobbies:details.hobbies}</code></td><td>Map fields and nested fields into a new object (JMESPath-style, not supported everywhere)</td></tr></tbody></table><h2>🧰 Where You’ll Meet It</h2><ul><li><code>kubectl get pods -o jsonpath=&#39;{.items[*].metadata.name}&#39;</code></li><li>Jayway JSONPath in Java, REST Assured assertions</li><li>Karate, Postman and Newman test scripts</li><li>Nginx, Grafana and Prometheus JSON scrapers</li></ul><blockquote><p>💡 For heavier transformation on the command line, <code>jq</code> is usually the better tool — JSONPath selects, <code>jq</code> selects <em>and</em> reshapes.</p></blockquote><h2>📚 Resources</h2><ul><li><a href="https://www.rfc-editor.org/rfc/rfc9535.html">RFC 9535 — JSONPath</a></li><li><a href="https://jsonpath.com">Try expressions online (jsonpath.com)</a></li><li><a href="https://cburgmer.github.io/json-path-comparison/">Comparison of implementations</a></li></ul><p>Original author: <a href="https://gist.github.com/mackoj/5786f8b95da0a82e8e003f444c4295bf">https://gist.github.com/mackoj/5786f8b95da0a82e8e003f444c4295bf</a></p>`,28)]]))}};export{a as default};